use std::collections::VecDeque;impl Solution{pub fn shortest_distance(g:Vec<Vec<i32>>)->i32{let(m,n)=(g.len(),g[0].len());let(mut sum,mut reach,mut bc)=(vec![vec![0;m.max(n)];m],vec![vec![0;n];m],0);sum=vec![vec![0;n];m];let d=[(1,0),(-1,0),(0,1),(0,-1)];for i in 0..m{for j in 0..n{if g[i][j]==1{bc+=1;let mut q=VecDeque::from([(i,j)]);let mut v=vec![vec![false;n];m];let mut dist=0;while !q.is_empty(){dist+=1;for _ in 0..q.len(){let(x,y)=q.pop_front().unwrap();for &(a,b)in&d{let r=x as i32+a;let c=y as i32+b;if r>=0&&c>=0&&r<m as i32&&c<n as i32&&!v[r as usize][c as usize]&&g[r as usize][c as usize]==0{v[r as usize][c as usize]=true;sum[r as usize][c as usize]+=dist;reach[r as usize][c as usize]+=1;q.push_back((r as usize,c as usize));}}}}}}}let mut ans=i32::MAX;for i in 0..m{for j in 0..n{if g[i][j]==0&&reach[i][j]==bc{ans=ans.min(sum[i][j]);}}}if ans==i32::MAX{-1}else{ans}}}
